}

// --- Interrupt Service Routines ---

// ISR for external button press
void buttonISR() {
  // Set a flag to be processed in the main loop
  // Keep ISR short and fast! Avoid Serial.print(), delay(), or complex logic here.
  buttonPressed = true;
}

// ISR for Timer1 Compare Match A
ISR(TIMER1_COMPA_vect) {
  digitalWrite(timerLedPin, !digitalRead(timerLedPin)); // Toggle timer LED
  // Optionally count or perform other periodic tasks
  timerCounter++;
  if (timerCounter % 2 == 0) { // Every 1 second (two 500ms intervals)
    // Serial.println("Timer interrupt!"); // Avoid Serial.print() in ISR in real applications
  }
}
