5. Combine these elements in a single program, ensuring proper interaction and avoiding conflicts.","procedure":["Connect the Arduino Uno to your computer and open the Arduino IDE. Select the correct board and port.","Construct the circuit for the LED clock: Connect an LED (with a 220 Ohm resistor) to Arduino digital pin 7. This LED will blink with the generated clock signal.","Construct the circuit for the waveform generation: Connect a piezo buzzer to Arduino digital pin 9 (a PWM capable pin).","Construct the circuit for the event counter: Connect a push button to Arduino digital pin 2 (external interrupt 0). Connect the other leg of the button to GND. Use `INPUT_PULLUP` in code.","Copy the provided Embedded C code into the Arduino IDE.","Compile and upload the code to your Arduino Uno board.","Open the Serial Monitor (baud rate 9600) to observe the counter values and other debug messages.","Observe the LED on pin 7 blinking at a fixed rate (e.g., once per second), demonstrating clock generation.","Listen to the piezo buzzer on pin 9, which should produce a continuous sweep of tones, demonstrating PWM waveform generation.","Press the push button connected to pin 2. Observe the counter value incrementing in the Serial Monitor with each press, demonstrating event counting."],"program":"```cpp
// Experiment 4: Real-time Applications - Clock, Waveform, Counter

// --- Clock Generation (LED Blink) using Timer2 --- 
// Toggles an LED on Pin 7 at 1Hz (0.5Hz square wave)
const int clockLedPin = 7;
volatile bool clockLedState = false;

// --- Waveform Generation (Buzzer Tone) using PWM --- 
// Sweeps tone on a piezo buzzer connected to Pin 9
const int buzzerPin = 9; // PWM capable pin

// --- Event Counter (Button Press) using External Interrupt --- 
// Counts button presses on Pin 2
const int buttonPin = 2; // Interrupt pin 0 on Arduino Uno
volatile unsigned long pressCount = 0; // Use unsigned long for counter
volatile bool buttonPressDetected = false; // Flag to indicate a press
unsigned long lastDebounceTime = 0;  // the last time the output pin was toggled
unsigned long debounceDelay = 50;    // the debounce time; increase if needed

void setup() {
  Serial.begin(9600);
  while (!Serial) {
    ; // wait for serial port to connect. Needed for native USB port only
  }
  Serial.println("--- Real-time Applications: Clock, Waveform, Counter ---");

  // --- Setup Clock Generation (Timer2 CTC Mode) ---
  pinMode(clockLedPin, OUTPUT);
  noInterrupts();           // Disable global interrupts
  TCCR2A = 0;               // Clear TCCR2A register
  TCCR2B = 0;               // Clear TCCR2B register
  TCNT2 = 0;                // Initialize counter value to 0
  // Set Compare Match Register for 1Hz (0.5Hz square wave) on 16MHz, prescaler 1024
  // (16,000,000 / 1024) / 2 = 7812.5 ticks/sec
  // OCR2A = 7812 for 1 second. (Max for 8-bit timer is 255, so need a different approach or timer for 1Hz)
  // For 1Hz with Timer2 (8-bit), we need to divide 16MHz by 1024 * (OCR2A + 1) = 2. So (OCR2A+1) = 16M / (1024 * 2) = 7812.5. This won't fit into 255.
  // Let's aim for a faster blink with Timer2, e.g., 4Hz (0.25s ON, 0.25s OFF)
  // (16,000,000 / 1024) / (OCR2A + 1) = 8 Hz (for toggling 4 times a second)
  // OCR2A = (16,000,000 / (1024 * 8)) - 1 = 1953.125 - 1 => won't fit 8-bit. Max prescaler for Timer2 is 1024.
  // We will achieve a 4Hz square wave by setting OCR2A to a value that causes an interrupt every 125ms.
  // (16,000,000 / 1024) / (OCR2A + 1) = 8 (interrupts per second for 4Hz wave, toggling twice per cycle)
  // OCR2A = (16000000 / (1024 * 8)) - 1 = 1953 - 1 = 1952. Too large for 8-bit Timer2 (0-255).
  // Let's use prescaler 64 and aim for ~10ms interval (100Hz toggle, 50Hz square wave) for Timer2 (Max 255).
  // (16,000,000 / 64) / (OCR2A + 1) = 100 Hz (interrupts every 10ms)
  // OCR2A = (16000000 / (64 * 100)) - 1 = 2500 - 1 = 2499. Still too large.
  // We need to cascade interrupts or use a different timer for very slow speeds with 8-bit Timer2.
  // For this experiment, let's target a blink visible, like 8Hz toggle (4Hz square wave).
  // With prescaler 1024, Timer2 runs at 16,000,000/1024 = 15625 Hz.
  // To toggle every 125ms (8 times per second), we need to count to 15625 * 0.125 = 1953. This is too large for OCR2A.
  // So, we'll use a software counter inside the Timer2 ISR to slow it down.
  // Timer2 with prescaler 1024 runs at 15625 ticks/sec. Max OCR2A = 255.
  // Let's set OCR2A to 249 (for ~15ms interrupt, 15625/250 = 62.5 interrupts/sec).
  // We will divide this by 62.5 / 2 = 31.25 times to get 1Hz. So, toggle LED after 31 times.

  OCR2A = 249; // Interrupt every (249+1) * 1024 / 16,000,000 = 0.016 seconds (16ms)
  TCCR2A |= (1 << WGM21); // CTC mode
  TCCR2B |= (1 << CS22) | (1 << CS21) | (1 << CS20); // Prescaler 1024
  TIMSK2 |= (1 << OCIE2A); // Enable Timer2 Compare Match A Interrupt

  // --- Setup Waveform Generation (PWM for Buzzer) ---
  pinMode(buzzerPin, OUTPUT);
  // No specific setup here, analogWrite() handles Timer setup for PWM.

  // --- Setup Event Counter (External Interrupt) ---
  pinMode(buttonPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(buttonPin), buttonPressISR, FALLING);

  interrupts();             // Enable global interrupts
  Serial.println("Setup complete. Monitoring events.");
}

// --- Loop Function (Main Program) ---
void loop() {
  // Waveform Generation (Buzzer tone sweep)
  static int pwmValue = 0;
  static int pwmDirection = 1;

  analogWrite(buzzerPin, pwmValue);
  pwmValue += pwmDirection;
  if (pwmValue >= 255 || pwmValue <= 0) {
    pwmDirection *= -1; // Reverse direction
  }
  delay(10); // Small delay for smooth sweep

  // Event Counter display
  if (buttonPressDetected) {
    Serial.print("Button Pressed! Count: ");
    Serial.println(pressCount);
    buttonPressDetected = false; // Reset the flag
  }
}

// --- Interrupt Service Routines (ISRs) ---

// ISR for Clock Generation (Timer2 Compare Match A)
// This ISR fires every ~16ms. We'll use a software counter to achieve 1Hz.
ISR(TIMER2_COMPA_vect) {
  static int softwareCounter = 0;
  softwareCounter++;
  // 1Hz requires 1 second. Each interrupt is ~16ms. So, 1000ms / 16ms = ~62.5 interrupts.
  // Let's toggle every 62 interrupts for approximately 1 second.
  if (softwareCounter >= 62) { 
    clockLedState = !clockLedState; // Toggle LED state
    digitalWrite(clockLedPin, clockLedState);
    softwareCounter = 0; // Reset counter
  }
}

// ISR for External Interrupt (Button Press)
void buttonPressISR() {
  // Basic debounce: Check if enough time has passed since last press
  if ((millis() - lastDebounceTime) > debounceDelay) {
    pressCount++;
    buttonPressDetected = true;
    lastDebounceTime = millis();
  }
}
