// Experiment 5: Exploring Different Communication Methods (UART & I2C)

// --- I2C Communication (for 16x2 LCD with I2C module) ---
// Include the Liquid Crystal I2C library
#include <Wire.h> // Required for I2C communication
#include <LiquidCrystal_I2C.h> // Library for I2C LCD

// Set the LCD address to 0x27 or 0x3F (check your specific module)
LiquidCrystal_I2C lcd(0x27, 16, 2); // LCD address, 16 columns and 2 rows

long i2c_counter = 0;

void setup() {
  // --- UART Communication Setup ---
  Serial.begin(9600); // Initialize serial communication at 9600 baud
  while (!Serial) {
    ; // wait for serial port to connect. Needed for native USB port only
  }
  Serial.println("--- Communication Methods: UART & I2C ---");
  Serial.println("UART: Initialized at 9600 baud.");

  // --- I2C Communication Setup ---
  Wire.begin(); // Initialize I2C bus
  lcd.init();   // Initialize the LCD
  if (!lcd.begin(16, 2)) {
    Serial.println("LCD initialization failed! Check wiring/address.");
    while (true);
  }
  lcd.backlight(); // Turn on backlight
  lcd.print("I2C LCD Initialized");
  lcd.setCursor(0, 1);
  lcd.print("Counter: ");
  Serial.println("I2C: LCD initialized at address 0x27 (or 0x3F).");
  Serial.println();
}

void loop() {
  // --- UART Communication (Sending data) ---
  Serial.print("UART Message: Loop counter = ");
  Serial.println(i2c_counter);

  // --- UART Communication (Receiving data) ---
  if (Serial.available()) {
    String incomingString = Serial.readStringUntil('\n');
    Serial.print("UART Received: ");
    Serial.println(incomingString);
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("Received:");
    lcd.setCursor(0, 1);
    lcd.print(incomingString.substring(0, 16)); // Display max 16 chars
    delay(2000); // Display received message for 2 seconds
    // Restore original LCD display after showing message
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("I2C LCD Initialized");
    lcd.setCursor(0, 1);
    lcd.print("Counter: ");
  }

  // --- I2C Communication (Displaying data on LCD) ---
  lcd.setCursor(9, 1); // Set cursor to the position for the counter value
  lcd.print("      "); // Clear previous value
  lcd.setCursor(9, 1);
  lcd.print(i2c_counter);
  i2c_counter++;

  delay(1000); // Delay for 1 second before next loop iteration
}
