  Serial.println("\n--- Bitwise Operations ---");
  Serial.print("val1 (binary): "); Serial.println(val1, BIN);
  Serial.print("val2 (binary): "); Serial.println(val2, BIN);

  Serial.print("val1 & val2 (AND): "); Serial.println(val1 & val2, BIN);
  Serial.print("val1 | val2 (OR):  "); Serial.println(val1 | val2, BIN);
  Serial.print("val1 ^ val2 (XOR): "); Serial.println(val1 ^ val2, BIN);
  Serial.print("~val1 (NOT):     "); Serial.println(~val1, BIN);
  Serial.print("val1 << 2 (Left Shift): "); Serial.println(val1 << 2, BIN);
