7. **Experiment:** Change the delay values in the code for both the LED and buzzer independently to alter their ON/OFF durations. Try making them blink/beep at different rates.
8. **Clean Up:** Disconnect wires and components safely."],"program":"/* --- Arduino C Code for LED & Buzzer Control --- */

const int ledPin = 13; // Arduino pin for LED
const int buzzerPin = 12; // Arduino pin for active buzzer

void setup() {
  pinMode(ledPin, OUTPUT);    // Set the LED pin as output
  pinMode(buzzerPin, OUTPUT); // Set the Buzzer pin as output
}

void loop() {
  digitalWrite(ledPin, HIGH);   // Turn the LED on
  digitalWrite(buzzerPin, HIGH); // Turn the Buzzer on
  delay(500);                   // Wait for 500 milliseconds

  digitalWrite(ledPin, LOW);    // Turn the LED off
  digitalWrite(buzzerPin, LOW);  // Turn the Buzzer off
  delay(500);                   // Wait for another 500 milliseconds
}

