8. **Test Stepper Motor:** Press and hold the push button. The stepper motor should rotate a fixed number of steps in one direction. Release the button, and the motor should stop.
9. **Experiment:** Modify the motor speed, direction, or the number of steps based on button presses. Add debouncing logic for the button if needed.
10. **Clean Up:** Disconnect wires and components safely."],"program":"/* --- Arduino C Code for DC Motor Control with L293D --- */

const int buttonPin = 2; // Button connected to Digital Pin 2
const int motorEnablePin = 9; // L293D Enable pin (optional, for speed control using PWM)
const int motorInput1 = 6;  // L293D Input 1
const int motorInput2 = 5;  // L293D Input 2

void setup() {
  Serial.begin(9600);
  pinMode(buttonPin, INPUT_PULLUP); // Button input with internal pull-up
  pinMode(motorInput1, OUTPUT);
  pinMode(motorInput2, OUTPUT);
  pinMode(motorEnablePin, OUTPUT);
  digitalWrite(motorEnablePin, HIGH); // Enable the motor driver (full speed, no PWM for now)
}

void loop() {
  if (digitalRead(buttonPin) == LOW) { // Button is pressed (LOW because of pull-up)
    Serial.println("Button Pressed - Motor ON");
    // Drive motor forward (or reverse by swapping HIGH/LOW on Input1/Input2)
    digitalWrite(motorInput1, HIGH);
    digitalWrite(motorInput2, LOW);
    // You can use analogWrite(motorEnablePin, 255) for full speed, or lower values for slower speed
  } else {
    Serial.println("Button Released - Motor OFF");
    // Stop motor
    digitalWrite(motorInput1, LOW);
    digitalWrite(motorInput2, LOW);
  }
  delay(50); // Small delay for stable readings and debouncing
}

